#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Always run from the repo root so .env and `uv run` resolve correctly.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

banner "promise-monitor · Google Sheets review queue"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Google Cloud project"
say "The service account that reads/writes the review sheet lives in a Google Cloud project."
say "Use an existing AdvoKC project or create one. Billing is NOT needed for the Sheets API."
open_url "https://console.cloud.google.com/projectcreate"
step "Either create a project (e.g. name: promise-monitor), or cancel and pick an existing one"
step "  from the project picker at the top of the console."
step "Copy the Project ID (lowercase, shown under the name; not the number)."
ask GCP_PROJECT_ID "Project ID:"
note "Only used to open the right console pages below; not saved."

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Enable the Google Sheets API"
open_url "https://console.cloud.google.com/apis/library/sheets.googleapis.com?project=${GCP_PROJECT_ID}"
step "Click 'Enable' (if it says 'Manage', it is already enabled)."
pause "Press Enter once the Sheets API shows as enabled…"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Create the service account"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=${GCP_PROJECT_ID}"
step "Service account name: promise-monitor  → 'Create and continue'."
step "Grant access: leave EMPTY (it needs no project roles; access comes from sharing the sheets)."
step "Click 'Done'. In the list, copy its email (…@${GCP_PROJECT_ID}.iam.gserviceaccount.com)."
ask SA_EMAIL "Service account email:"
note "You'll share both spreadsheets with this address."

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Create its JSON key (kept outside the repo)"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=${GCP_PROJECT_ID}"
step "Click the promise-monitor account → 'Keys' tab → 'Add key' → 'Create new key' → JSON → Create."
step "A .json file downloads (usually to ~/Downloads)."
warn "If key creation is blocked ('iam.disableServiceAccountKeyCreation'), your Google"
warn "Workspace admin must allow it for this project; stop here and ask them."
ask DOWNLOADED_KEY "Path to the downloaded .json file:"
DOWNLOADED_KEY="${DOWNLOADED_KEY/#\~/$HOME}"
if [[ ! -f "$DOWNLOADED_KEY" ]]; then
  warn "No file at $DOWNLOADED_KEY; re-run the wizard once you have it."; exit 1
fi
KEY_EMAIL=$(python3 -I -c 'import json,sys; print(json.load(open(sys.argv[1])).get("client_email",""))' "$DOWNLOADED_KEY" 2>/dev/null || true)
if [[ "$KEY_EMAIL" != "$SA_EMAIL" ]]; then
  warn "That key belongs to '$KEY_EMAIL', not '$SA_EMAIL'."
  confirm "Use it anyway?" || exit 1
fi
KEY_DIR="$HOME/.config/promise-monitor"
KEY_PATH="$KEY_DIR/service-account.json"
say "The key will be moved to $KEY_PATH (mode 600), outside the git repo."
if confirm "Move it there now?"; then
  mkdir -p "$KEY_DIR" && chmod 700 "$KEY_DIR"
  mv "$DOWNLOADED_KEY" "$KEY_PATH" && chmod 600 "$KEY_PATH"
  printf '  %s✓ moved%s key → %s\n' "$GREEN" "$RESET" "$KEY_PATH"
else
  KEY_PATH="$DOWNLOADED_KEY"
  warn "Leaving it at $KEY_PATH; never copy it into the repo."
fi
write_env PM_GOOGLE_SERVICE_ACCOUNT_FILE "$KEY_PATH"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "The coordinators' review spreadsheet"
say "This is the real review queue: one tab per meter plus a 'coordinators' tab."
open_url "https://sheets.new"
step "Name it e.g. 'Promise Tracker – Coordinator Review' (top-left title)."
step "Share → add  $SA_EMAIL  as Editor → untick 'Notify people' → Share."
step "Also share it with your meter coordinators (Editor) whenever you're ready."
step "Copy the sheet's URL from the address bar."
ask REVIEW_URL "Review sheet URL (or just its ID):"
REVIEW_ID=$(printf '%s' "$REVIEW_URL" | sed -E 's#.*/spreadsheets/d/([A-Za-z0-9_-]+).*#\1#')
write_env PM_REVIEW_SPREADSHEET_ID "$REVIEW_ID"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "A separate TEST spreadsheet"
say "The live integration test creates and deletes a tab, so it must never touch the real queue."
open_url "https://sheets.new"
step "Name it 'promise-monitor TEST (safe to wipe)'."
step "Share → add  $SA_EMAIL  as Editor → untick 'Notify people' → Share."
step "Copy its URL."
ask TEST_URL "Test sheet URL (or ID):"
TEST_ID=$(printf '%s' "$TEST_URL" | sed -E 's#.*/spreadsheets/d/([A-Za-z0-9_-]+).*#\1#')
if [[ "$TEST_ID" == "$REVIEW_ID" ]]; then
  warn "That's the review sheet. The test sheet must be a different spreadsheet."; exit 1
fi
write_env PM_TEST_SPREADSHEET_ID "$TEST_ID"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Verify"
say "1) Live round trip against the TEST sheet (creates and deletes one tab):"
if PM_TEST_SPREADSHEET_ID="$TEST_ID" PM_GOOGLE_SERVICE_ACCOUNT_FILE="$KEY_PATH" \
   uv run pytest -q -m integration tests/integration/test_sheets_live.py; then
  printf '  %s✓ Sheets access works%s\n' "$GREEN" "$RESET"
else
  warn "The test failed. Usual causes: API not enabled (stage 2), or the TEST sheet not shared"
  warn "with $SA_EMAIL as Editor (stage 6). Fix it and re-run; saved values are kept."
  exit 1
fi
say ""
say "2) First real sync: creates the 'coordinators' tab and pushes any drafts/leads"
say "   waiting in the database to the REVIEW sheet. Nothing is published."
if confirm "Run 'promise-monitor review-sync' against the review sheet now?"; then
  uv run promise-monitor review-sync || { warn "review-sync failed; see the message above."; exit 1; }
else
  SKIPPED+=("first sync: run 'uv run promise-monitor review-sync'")
fi
pause "Press Enter to continue…"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Assign coordinators"
open_url "https://docs.google.com/spreadsheets/d/${REVIEW_ID}/edit"
step "Open the 'coordinators' tab: one row per active meter."
step "Fill 'coordinator_name' and 'email' for each meter (leave 'active' = yes)."
step "Unassigned meters fall back to the admin (PM_ADMIN_EMAIL) and are reported on each sync."
step "Don't rename meter tabs or column headers; rows can be sorted and filtered freely."
say ""
say "Coordinators review in their meter's tab: edit 'headline'/'body_markdown' if needed,"
say "then set 'decision' to approve / edit / reject (leads: dismiss). Each sync re-checks"
say "edited text and writes the outcome to 'qa_result'."
pause "Press Enter when done…"

finish
}

run_wizard "$@"; exit
